package com.bank.dedup.model;

import java.math.BigDecimal;
import java.util.Objects;

public class TradeConfirmation {
    private final String tradeId;
    private final String symbol;
    private final BigDecimal amount;
    private final String venue;  // BSE or NSE

    public TradeConfirmation(String tradeId, String symbol, BigDecimal amount, String venue) {
        this.tradeId = tradeId;
        this.symbol = symbol;
        this.amount = amount;
        this.venue = venue;
    }

    public String getTradeId() { return tradeId; }
    public String getSymbol() { return symbol; }
    public BigDecimal getAmount() { return amount; }
    public String getVenue() { return venue; }

    // equals/hashCode based on tradeId ONLY (for distinct() by trade ID)
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof TradeConfirmation t)) return false;
        return Objects.equals(tradeId, t.tradeId);
    }

    @Override
    public int hashCode() { return Objects.hash(tradeId); }

    @Override
    public String toString() {
        return tradeId + " " + symbol + " Rs." + amount + " (" + venue + ")";
    }
}
