// Reusable distinctByKey utility
package com.bank.dedup.util;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import java.util.function.Predicate;

public final class StreamUtils {

    private StreamUtils() {}

    /**
     * Returns a Predicate that tracks seen keys and returns true only for the first
     * occurrence of each key. Thread-safe for parallel streams.
     */
    public static <T> Predicate<T> distinctByKey(Function<? super T, ?> keyExtractor) {
        Set<Object> seen = ConcurrentHashMap.newKeySet();
        return t -> seen.add(keyExtractor.apply(t));  // add returns false if already present
    }
}
