package com.bank.dedup.service;

import com.bank.dedup.dto.DedupReport;
import com.bank.dedup.model.TradeConfirmation;
import com.bank.dedup.util.StreamUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class DedupService {

    private final List<TradeConfirmation> confirmations = List.of(
        new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "BSE"),
        new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "NSE"),  // duplicate ID!
        new TradeConfirmation("TRD-002", "TCS",      new BigDecimal("176000"), "BSE"),
        new TradeConfirmation("TRD-003", "RELIANCE", new BigDecimal("123750"), "BSE"),  // same symbol as TRD-001!
        new TradeConfirmation("TRD-002", "TCS",      new BigDecimal("176000"), "NSE"),  // duplicate ID!
        new TradeConfirmation("TRD-004", "HDFC",     new BigDecimal("330150"), "BSE"),
        new TradeConfirmation("TRD-005", "TCS",      new BigDecimal("88750"),  "NSE")   // same symbol as TRD-002!
    );

    public DedupReport deduplicate() {

        // ═══ 1. DISTINCT BY VALUE: uses equals/hashCode (based on tradeId) ═══
        List<TradeConfirmation> byValue = confirmations.stream()
            .distinct()                              // uses TradeConfirmation.equals (tradeId)
            .toList();
        log.info("By value (distinct): {} → {}", confirmations.size(), byValue.size());

        // ═══ 2. DISTINCT BY TRADE ID: using distinctByKey utility ═══
        List<TradeConfirmation> byTradeId = confirmations.stream()
            .filter(StreamUtils.distinctByKey(TradeConfirmation::getTradeId))
            .toList();
        log.info("By tradeId (distinctByKey): {} → {}", confirmations.size(), byTradeId.size());

        // ═══ 3. DISTINCT BY SYMBOL: first trade per symbol ═══
        List<TradeConfirmation> bySymbol = confirmations.stream()
            .filter(StreamUtils.distinctByKey(TradeConfirmation::getSymbol))
            .toList();
        log.info("By symbol (distinctByKey): {} → {}", confirmations.size(), bySymbol.size());

        // ═══ 4. ALTERNATIVE: toMap for distinct by key ═══
        List<TradeConfirmation> byTradeIdAlt = confirmations.stream()
            .collect(Collectors.toMap(
                TradeConfirmation::getTradeId, t -> t, (first, second) -> first))
            .values().stream()
            .sorted(Comparator.comparing(TradeConfirmation::getTradeId))
            .toList();

        return new DedupReport(
            confirmations.size(),
            byTradeId.size(),
            bySymbol.size(),
            byValue.size(),
            byTradeId.stream().map(TradeConfirmation::toString).toList(),
            bySymbol.stream().map(TradeConfirmation::toString).toList(),
            byValue.stream().map(TradeConfirmation::toString).toList()
        );
    }
}
