package com.bank.dedup.service;

import com.bank.dedup.util.StreamUtils;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class DistinctByKeyTest {

    @Test
    void distinctByValueUsingDistinct() {
        List<String> unique = Stream.of("RELIANCE", "TCS", "RELIANCE", "HDFC", "TCS")
            .distinct().toList();
        assertThat(unique).containsExactly("RELIANCE", "TCS", "HDFC");
    }

    @Test
    void distinctByKeyExtractor() {
        record Emp(String id, String name) {}
        var emps = List.of(new Emp("E1", "Rajesh"), new Emp("E2", "Priya"),
            new Emp("E1", "Rajesh Updated"), new Emp("E3", "Amit"));

        List<Emp> uniqueById = emps.stream()
            .filter(StreamUtils.distinctByKey(Emp::id))
            .toList();

        assertThat(uniqueById).hasSize(3);
        assertThat(uniqueById.get(0).name()).isEqualTo("Rajesh");  // first E1 kept
    }

    @Test
    void distinctByMultipleFields() {
        record Trade(String symbol, String side) {}
        var trades = List.of(new Trade("TCS", "BUY"), new Trade("TCS", "SELL"),
            new Trade("TCS", "BUY"), new Trade("HDFC", "BUY"));

        List<Trade> unique = trades.stream()
            .filter(StreamUtils.distinctByKey(t -> t.symbol() + "|" + t.side()))
            .toList();

        assertThat(unique).hasSize(3);  // TCS|BUY, TCS|SELL, HDFC|BUY
    }

    @Test
    void toMapAlternativeForDistinctByKey() {
        record Emp(String id, String name) {}
        var emps = List.of(new Emp("E1", "Rajesh"), new Emp("E1", "Updated"));

        List<Emp> unique = emps.stream()
            .collect(java.util.stream.Collectors.toMap(Emp::id, e -> e, (a, b) -> a))
            .values().stream().toList();

        assertThat(unique).hasSize(1);
        assertThat(unique.get(0).name()).isEqualTo("Rajesh");  // first kept
    }

    @Test
    void distinctPreservesFirstOccurrenceOrder() {
        List<String> result = Stream.of("C", "A", "B", "A", "C")
            .distinct().toList();
        assertThat(result).containsExactly("C", "A", "B");  // first-occurrence order
    }
}
